-- readme_snapshot.sql: the exact counts behind the 'Where it stands' table of README.md.
-- Run in the Supabase SQL editor (about 64 rows, 10 to 30 seconds; the editor shows at most 100 rows).
-- Paste the results into the README table, set the as-of date, and refresh at each milestone.
-- Created 2026-10-28. Dollar-quoted on purpose (the user's environment corrupts straight quotes on paste).
SELECT $$Universe$$, $$securities (tickers incl. SPY)$$, (SELECT COUNT(*) FROM securities)::text UNION ALL SELECT $$Universe$$, $$entities$$, (SELECT COUNT(*) FROM entities)::text UNION ALL SELECT $$Universe$$, $$sealed tickers (explore_sealed_tickers)$$, (SELECT COUNT(*) FROM explore_sealed_tickers)::text UNION ALL SELECT $$Events$$, $$events$$, (SELECT COUNT(*) FROM events)::text UNION ALL SELECT $$Events$$, $$earliest event date$$, (SELECT MIN(event_date::date) FROM events)::text UNION ALL SELECT $$Events$$, $$latest event date$$, (SELECT MAX(event_date::date) FROM events)::text UNION ALL SELECT $$Events$$, $$event types$$, (SELECT COUNT(*) FROM event_types)::text UNION ALL SELECT $$Events$$, $$events with a source filing$$, (SELECT COUNT(DISTINCT event_id) FROM event_source_filings)::text UNION ALL SELECT $$Events$$, $$events with a reaction row$$, (SELECT COUNT(DISTINCT event_id) FROM event_market_reactions_corrected)::text UNION ALL SELECT $$Events$$, $$events with an entity link$$, (SELECT COUNT(DISTINCT event_id) FROM event_entity_relationships)::text UNION ALL SELECT $$Filings$$, $$8-K filings (sec_8k_filings)$$, (SELECT COUNT(*) FROM sec_8k_filings)::text UNION ALL SELECT $$Filings$$, $$10-K and 10-Q filings (sec_filings)$$, (SELECT COUNT(*) FROM sec_filings)::text UNION ALL SELECT $$Filings$$, $$AI classifications (filing_ai_classifications)$$, (SELECT COUNT(*) FROM filing_ai_classifications)::text UNION ALL SELECT $$Filings$$, $$classifications with a human verdict$$, (SELECT COUNT(*) FROM filing_ai_classifications WHERE human_verdict IS NOT NULL)::text UNION ALL SELECT $$Prices$$, $$daily price rows (market_prices)$$, (SELECT COUNT(*) FROM market_prices)::text UNION ALL SELECT $$Prices$$, $$securities with prices$$, (SELECT COUNT(DISTINCT security_id) FROM market_prices)::text UNION ALL SELECT $$Prices$$, $$first price date$$, (SELECT MIN(price_date) FROM market_prices)::text UNION ALL SELECT $$Prices$$, $$last price date$$, (SELECT MAX(price_date) FROM market_prices)::text UNION ALL SELECT $$Prices$$, $$as-quoted adjustment factor rows$$, (SELECT COUNT(*) FROM price_adjustment_factors)::text UNION ALL SELECT $$Financials$$, $$quarterly statements$$, (SELECT COUNT(*) FROM financial_statements WHERE period_type = $$quarterly$$)::text UNION ALL SELECT $$Financials$$, $$annual statements$$, (SELECT COUNT(*) FROM financial_statements WHERE period_type = $$annual$$)::text UNION ALL SELECT $$Financials$$, $$financial_metrics rows$$, (SELECT COUNT(*) FROM financial_metrics)::text UNION ALL SELECT $$Financials$$, $$first statement period end$$, (SELECT MIN(period_end) FROM financial_statements)::text UNION ALL SELECT $$Financials$$, $$last statement period end$$, (SELECT MAX(period_end) FROM financial_statements)::text UNION ALL SELECT $$External conditions$$, $$macro releases (macro_data_releases)$$, (SELECT COUNT(*) FROM macro_data_releases)::text UNION ALL SELECT $$External conditions$$, $$macro_long rows$$, (SELECT COUNT(*) FROM macro_long)::text UNION ALL SELECT $$External conditions$$, $$FOMC meetings$$, (SELECT COUNT(*) FROM fomc_meetings)::text UNION ALL SELECT $$External conditions$$, $$company sentiment rows$$, (SELECT COUNT(*) FROM company_sentiment_timeline)::text UNION ALL SELECT $$External conditions$$, $$global events$$, (SELECT COUNT(*) FROM global_events)::text UNION ALL SELECT $$External conditions$$, $$news articles$$, (SELECT COUNT(*) FROM news_articles)::text UNION ALL SELECT $$External conditions$$, $$government decisions$$, (SELECT COUNT(*) FROM government_decisions)::text UNION ALL SELECT $$External conditions$$, $$government decisions with text$$, (SELECT COUNT(*) FROM government_decision_text)::text UNION ALL SELECT $$External conditions$$, $$law stage dates$$, (SELECT COUNT(*) FROM law_stage_dates)::text UNION ALL SELECT $$Reactions$$, $$reaction rows (event_market_reactions_corrected)$$, (SELECT COUNT(*) FROM event_market_reactions_corrected)::text UNION ALL SELECT $$Reactions$$, $$entity reaction rows (multi-entity events)$$, (SELECT COUNT(*) FROM event_entity_reactions)::text UNION ALL SELECT $$Reactions$$, $$pre-context rows$$, (SELECT COUNT(*) FROM event_pre_context)::text UNION ALL SELECT $$Reactions$$, $$ripple timeline rows$$, (SELECT COUNT(*) FROM event_ripple_timeline)::text UNION ALL SELECT $$Reactions$$, $$events with a ripple timeline$$, (SELECT COUNT(DISTINCT event_id) FROM event_ripple_timeline)::text UNION ALL SELECT $$Reactions$$, $$point-in-time firm-state rows (event_firm_state_pit)$$, (SELECT COUNT(*) FROM event_firm_state_pit)::text UNION ALL SELECT $$Reactions$$, $$analysis set (event_analysis_set)$$, (SELECT COUNT(*) FROM event_analysis_set)::text UNION ALL SELECT $$Labels (all events)$$, t.name, COUNT(DISTINCT et.event_id)::text FROM event_tags et JOIN tags t ON t.id = et.tag_id WHERE t.name IN ($$rewarded$$, $$punished$$, $$muted$$, $$diverged_from_fundamentals$$) GROUP BY t.name UNION ALL SELECT $$Flag ledger$$, status, COUNT(*)::text FROM flag_ledger GROUP BY status UNION ALL SELECT $$Exclusions$$, reason || $$ ($$ || severity || $$)$$, COUNT(*)::text FROM event_exclusions GROUP BY reason, severity UNION ALL SELECT $$Database$$, $$size on disk$$, pg_size_pretty(pg_database_size(current_database())) UNION ALL SELECT $$Database$$, $$tables$$, COUNT(*)::text FROM information_schema.tables WHERE table_schema = $$public$$ AND table_type = $$BASE TABLE$$ UNION ALL SELECT $$Database$$, $$views$$, COUNT(*)::text FROM information_schema.tables WHERE table_schema = $$public$$ AND table_type = $$VIEW$$ ORDER BY 1, 2;